            align-items: center;
        }
        .header-side {
            width: 25%;
            font-size: 1.4rem;
            font-weight: bold;
        }
        .header-side.right {
            text-align: right;
        }
        .header-center {
            width: 50%;
            text-align: center;
            font-size: 3rem;
            font-weight: 900;
            letter-spacing: 6px;
            text-transform: uppercase;
            font-family: "Times New Roman", Times, serif;
        }
        /* Grid Layout */
        .newspaper-grid {
            display: grid;
            grid-template-columns: 1fr 1fr 1fr;
            gap: 24px;
        }
        .column {
            display: flex;
            flex-direction: column;
        }
        .column:not(:last-child) {
            border-right: 1px solid #1c1a17;
            padding-right: 15px;
        }
